-- MI-17 extends the shared Core POS; it does not create a second POS ledger.
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_pos_outlet(outlet_id UUID PRIMARY KEY REFERENCES "{{TENANT_SCHEMA}}".outlet(id) ON DELETE RESTRICT,property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,outlet_type VARCHAR(20) NOT NULL,service_rate NUMERIC(7,4) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,CONSTRAINT ck_hospitality_pos_outlet_type CHECK(outlet_type IN('RESTAURANT','BAR','ROOM_SERVICE','MINIBAR','RETAIL','SPA')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_pos_sale_context(pos_sale_id UUID PRIMARY KEY REFERENCES "{{TENANT_SCHEMA}}".pos_sale(id) ON DELETE RESTRICT,stay_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest_stay(id) ON DELETE RESTRICT,folio_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_folio(id) ON DELETE RESTRICT,window_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_folio_window(id) ON DELETE RESTRICT,order_source VARCHAR(20) NOT NULL DEFAULT 'OUTLET',guest_count INTEGER,room_charge_status VARCHAR(16),folio_transaction_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_folio_transaction(id) ON DELETE RESTRICT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,CONSTRAINT ck_hospitality_pos_source CHECK(order_source IN('OUTLET','ROOM_SERVICE','MINIBAR','SPA','GUEST_PORTAL')),CONSTRAINT ck_hospitality_pos_room_status CHECK(room_charge_status IS NULL OR room_charge_status IN('PENDING','POSTED','REVERSED','FAILED')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_meal_entitlement(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),stay_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest_stay(id) ON DELETE RESTRICT,entitlement_code VARCHAR(64) NOT NULL,valid_date DATE NOT NULL,quantity INTEGER NOT NULL,consumed INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,CONSTRAINT ck_hospitality_meal_quantity CHECK(quantity>0 AND consumed>=0 AND consumed<=quantity),UNIQUE(stay_id,entitlement_code,valid_date));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_meal_consumption(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entitlement_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_meal_entitlement(id) ON DELETE RESTRICT,quantity INTEGER NOT NULL,pos_sale_id UUID REFERENCES "{{TENANT_SCHEMA}}".pos_sale(id) ON DELETE RESTRICT,idempotency_key VARCHAR(128) NOT NULL UNIQUE,consumed_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT ck_hospitality_meal_consumption_qty CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_kitchen_ticket(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),pos_sale_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".pos_sale(id) ON DELETE RESTRICT,status VARCHAR(16) NOT NULL DEFAULT 'QUEUED',station_code VARCHAR(64),sequence_no BIGSERIAL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),started_at TIMESTAMPTZ,ready_at TIMESTAMPTZ,served_at TIMESTAMPTZ,CONSTRAINT ck_hospitality_kitchen_status CHECK(status IN('QUEUED','PREPARING','READY','SERVED','CANCELLED')),UNIQUE(pos_sale_id));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_pos_event_outbox(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),pos_sale_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".pos_sale(id) ON DELETE RESTRICT,event_type VARCHAR(40) NOT NULL,payload JSONB NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'PENDING',idempotency_key VARCHAR(128) NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),processed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS ix_hospitality_pos_room_charge ON "{{TENANT_SCHEMA}}".hospitality_pos_sale_context(folio_id,room_charge_status);
